// STE-303 — tracker-config write helper: builds the role-to-status proposal,
// renders a unified diff against any baseline, prompts the operator via
// AskUserQuestion (approve / edit / cancel), and routes approve through
// STE-302's writeTrackerConfig.
//
// The helper is dependency-injected so unit tests can script every input
// (fetchStatuses, askUserQuestion, writeTrackerConfig, chooseRole). The
// /setup skill body (Step Nb) wires the real implementations: MCP-driven
// status fetch, AskUserQuestion tool call, STE-302's writeTrackerConfig.
//
// Outcomes (literal token = capability-key surfaced in the closing summary):
//   - succeeded               → proposal approved + write fired
//   - unchanged               → baseline == proposal, no prompt, no write
//   - cancelled               → operator cancelled, no write
//   - skipped_mode_none       → tracker mode == "none", vacuous
//   - skipped_adapter_limit   → adapter lacks list_project_statuses capability
//   - mcp_unavailable         → MCP fetch threw; NFR-10 canonical refusal

import {
  CANONICAL_ROLES,
  readTrackerConfig,
  type Role,
  type TrackerConfig,
} from "./tracker_config";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type Outcome =
  | "succeeded"
  | "unchanged"
  | "cancelled"
  | "skipped_mode_none"
  | "skipped_adapter_limit"
  | "mcp_unavailable";

export interface Proposal {
  tracker_key: string;
  statuses: string[];
  roles: Record<string, string | null>;
  reasoning: Record<string, string>;
}

export interface ChooseRoleResult {
  status: string | null;
  reasoning: string;
}

export interface ProposalDeps {
  fetchStatuses: (adapterKey: string) => Promise<string[]>;
  askUserQuestion: (spec: unknown) => Promise<Record<string, unknown>>;
  writeTrackerConfig: (specsDir: string, config: TrackerConfig) => void;
  chooseRole: (role: string, statuses: string[]) => ChooseRoleResult;
}

export interface AdapterCapabilities {
  list_project_statuses?: boolean;
}

export interface RunTrackerConfigWriteOpts {
  specsDir: string;
  adapterKey: string;
  mode: string;
  autoApprove: boolean;
  deps: ProposalDeps;
  adapterCapabilities?: AdapterCapabilities;
}

export interface RunResult {
  outcome: Outcome;
  message?: string;
}

// ---------------------------------------------------------------------------
// AC-STE-303.11 — closing-summary capability key literals
// ---------------------------------------------------------------------------

export const CLOSING_SUMMARY_KEYS = [
  "tracker_config_write_succeeded",

// STE-302 — Per-project tracker-config.yaml loader + role/status mappers.
//
// `specs/tracker-config.yaml` declares the project's verbatim tracker statuses
// and the mapping from the canonical four-role enum to those statuses. The
// canonical roles — `initial`, `in_progress`, `in_review`, `done` — are the
// single tracker-agnostic vocabulary the rest of the toolkit speaks; each
// project declares how those roles map to its tracker's actual workflow
// labels (e.g., Linear's "Backlog" / "In Progress" / "In Review" / "Done").
//
// Schema:
//
//     tracker_key: linear            # active adapter's `name:` field
//     statuses:                      # >= 1 entry, verbatim tracker labels
//       - Backlog
//       - In Progress
//       - In Review
//       - Done
//     roles:                         # MUST declare all four canonical roles
//       initial: Backlog             # value MUST appear in `statuses:`
//       in_progress: In Progress
//       in_review: In Review
//       done: Done
//
// Anything outside that surface throws `TrackerConfigShapeError` carrying
// the NFR-10 canonical refusal shape (Refusing: / Remedy: / Context:) so
// callers can render it verbatim. `readTrackerConfig` returns `null` when
// the file is absent — callers fall back to per-adapter defaults.

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

export type Role = "initial" | "in_progress" | "in_review" | "done";

export const CANONICAL_ROLES: readonly Role[] = ["initial", "in_progress", "in_review", "done"];

export interface TrackerConfig {
  tracker_key: string;
  statuses: string[];
  roles: Record<Role, string>;
}

const CONFIG_FILENAME = "tracker-config.yaml";

/**
 * Thrown when the tracker-config file or in-memory object violates the
 * schema. NFR-10 canonical refusal shape: the message fuses
 * Refusing / Remedy / Context so callers can surface it verbatim.
 */
export class TrackerConfigShapeError extends Error {
  readonly reason: string;
  constructor(reason: string, remedy?: string, context?: string) {
    const remedyLine =
      remedy ?? "fix specs/tracker-config.yaml to conform to the documented schema and re-run.";
    const contextLine = context ?? `mode=tracker-config, file=specs/${CONFIG_FILENAME}`;
    super(
      [
        `Refusing: ${reason}`,
        `Remedy: ${remedyLine}`,
        `Context: ${contextLine}`,
